from collections import OrderedDict

def cache_sim(capacity, ttl, ops):
    cache = OrderedDict()  # key -> (value, write_time)
    results = []
    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op
            # remove expired entries lazily check for this key
            if key in cache:
                v, wt = cache[key]
                if t >= wt + ttl:
                    del cache[key]
            if key in cache:
                del cache[key]
                cache[key] = (value, t)
            else:
                if len(cache) >= capacity:
                    # evict expired entries first if any (not required but let's just evict LRU)
                    # remove least recently used
                    cache.popitem(last=False)
                cache[key] = (value, t)
        else:
            _, t, key = op
            if key in cache:
                v, wt = cache[key]
                if t >= wt + ttl:
                    del cache[key]
                    results.append(-1)
                else:
                    cache.move_to_end(key)
                    results.append(v)
            else:
                results.append(-1)
    return results

